import { words } from 'es-toolkit/string';
import { groupBy } from 'es-toolkit/array';
import { truncate } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, (r) => r.age);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
cat > fuzz.mjs <<'EOF'
import {build} from 'esbuild';
import _ from 'lodash';
const o=await build({entryPoints:['out/module.ts'],bundle:true,format:'esm',write:false});
const m=await import('data:text/javascript,'+encodeURIComponent(o.outputFiles[0].text));
const A='abcXYZABCdef0123 -_.9Q';let bad=0;
const r=n=>Math.floor(Math.random()*n);
for(let i=0;i<200000;i++){let s='';for(let j=r(41);j--;)s+=A[r(A.length)];
 if(JSON.stringify(_.words(s))!==JSON.stringify(m.tokens(s))){if(bad++<5)console.log('tok',JSON.stringify(s),_.words(s),m.tokens(s));}}
for(let i=0;i<20000;i++){let s='';for(let j=r(201);j--;)s+=String.fromCharCode(32+r(95));
 if(_.truncate(s,{length:24})!==m.preview(s)){if(bad++<5)console.log('prev',s);}}
console.log('bad',bad);
EOF
cp fuzz.mjs tools/_fuzz.mjs; node tools/_fuzz.mjs; rm tools/_fuzz.mjs fuzz.mjs; npm run size -- src/module.ts; npm run size -- out/module.ts

